          "comment": "If not NULL, this column indicates that the REST service is currently \\"in development\\" and holds the name(s) of the developer(s) who is(/are) allowed to work with the service in the \\"$.developers\\" string array. REST services with this column not being NULL may use the same url_host+url_context_root context path as existing services. MariaDB REST Daemons only serve REST services with this column being NULL, unless they are bootstrapped with --mrs-development <user> which sets JSON_UNQUOTE(JSON_EXTRACT(rest_daemon.attributes, \\"$.developer\\")). When bootstrapped with the --mrs-development <user> option the MariaDB REST Daemon also serves REST services marked \\"in development\\" with this column\'s \\"$.developers\\" including the same name as the <user> specified during bootstrap, while these REST services marked \\"in development\\" take priority over services with the same url_host+url_context_root context path and this column being NULL.",
