    {
      "name": "JSON_STORAGE_SIZE",
      "kind": "function",
      "parameters": [{"mode": null, "name": "doc", "type": "JSON"}],
      "returns": "INT",
      "body": "BEGIN\\n    IF NOT @@version LIKE \'%MariaDB%\' THEN\\n        RETURN JSON_STORAGE_SIZE(doc);\\n    ELSE\\n        RETURN OCTET_LENGTH(doc);\\n    END IF;\\nEND",
      "deterministic": true,
      "data_access": "NO SQL",
      "security": "INVOKER",
      "definer": null,
      "comment": null,
      "aggregate": false,
      "soname": null,
      "source": 5,
      "range": {"start": {"line": 795, "character": 0}, "end": {"line": 802, "character": 3}},
      "selection_range": {"start": {"line": 795, "character": 16}, "end": {"line": 795, "character": 35}}
