      "body": "BEGIN\\n    INSERT INTO `audit_log` (\\n        table_name, dml_type, old_row_data, new_row_data, old_row_id, new_row_id, changed_by, changed_at)\\n    VALUES (\\n        \\"rest_daemon\\",\\n        \\"INSERT\\",\\n        NULL,\\n        JSON_OBJECT(\\n            \\"id\\", NEW.id,\\n            \\"options\\", NEW.options),\\n        NULL,\\n        NEW.id,\\n        CURRENT_USER(),\\n        CURRENT_TIMESTAMP\\n    );\\nEND",
