    {
      "name": "rest_daemon_AFTER_UPDATE_AUDIT_LOG",
      "timing": "AFTER",
      "events": "UPDATE",
      "table": "rest_daemon",
      "body": "BEGIN\\n    IF (COALESCE(OLD.options, \'\') <> COALESCE(NEW.options, \'\')) THEN\\n        INSERT INTO `audit_log` (\\n            table_name, dml_type, old_row_data, new_row_data, old_row_id, new_row_id, changed_by, changed_at)\\n        VALUES (\\n            \\"rest_daemon\\",\\n            \\"UPDATE\\",\\n            JSON_OBJECT(\\n                \\"id\\", OLD.id,\\n                \\"options\\", OLD.options),\\n            JSON_OBJECT(\\n                \\"id\\", NEW.id,\\n                \\"options\\", NEW.options),\\n            OLD.id,\\n            NEW.id,\\n            CURRENT_USER(),\\n            CURRENT_TIMESTAMP\\n        );\\n    END IF;\\nEND",
      "order": null,
