    {
      "name": "url_host_BEFORE_DELETE",
      "timing": "BEFORE",
      "events": "DELETE",
      "table": "url_host",
      "body": "BEGIN\\n\\tDELETE FROM `url_host_alias` WHERE `url_host_id` = OLD.`id`;\\nEND",
      "order": null,
      "definer": "CURRENT_USER",
      "update_columns": [],
      "source": 6,
      "range": {"start": {"line": 50, "character": 0}, "end": {"line": 53, "character": 3}},
